// https://twitter.com/SamuelAnn0924
// https://www.instagram.com/samuel_yan_1990/
// BarCODE

let mySize;
let seed = Math.random() * 2000;
let tile_Count = 40;
let cubes = [];
let noff = 0;
let w;
// colors
let colors2 = "73ff00-a940ff".split("-").map((a) => "#" + a);
// color #RRGGBBAA
let colors1 = "73ff00-a940ff".split("-").map((a) => "#" + a);

function setup() {
  //frameRate(25);
  pixelDensity(5);
  mySize = max(windowWidth, windowHeight);
  createCanvas(mySize, mySize);
  randomSeed(seed);
  background(10);

  w = width / tile_Count;

  for (let i = 0; i < tile_Count; i++) {
    for (let j = 0; j < tile_Count; j++) {
      let scaleX = random(0.25, 0.5);
      let scaleY = random(0.25, 0.5);
      let x = i * w;
      let y = j * w;
      let ShapeItem = int(random(1, 1));
      if (ShapeItem == 1) {
        cubes.push(new makeCubes(x, y, w * scaleX, w * scaleY));
      }
    }
  }
}

function draw() {
  randomSeed(seed);
  background(10,50);
  for (let c of cubes) {
    let numItem = int(random(0, 2));
    if (numItem == 1) {
      c.display1();
    } else {
      c.display2();
    }
    if (noff < w) {
      noff += 0.1;
    } else {
      noff = 0;
    }
  }
}

class makeCubes {
  constructor(x, y, wx, wy) {
    this.x = x;
    this.y = y;
    this.wx = wx;
    this.wy = wy;
    this.col1 = random(colors1);
    this.col2 = random(colors2);
    this.strWei = random([0.5, 1, 2, 1, 0.5]);
  }

  display1() {
    strokeWeight(this.strWei);
    //fill(this.col1);
    noFill();
    strokeCap(SQUARE);
    stroke(this.col1);
    let lineNum = int(w / (3 * this.strWei));
    for (let i = 0; i < lineNum + 1; i++) {
      push();
      translate(this.x + i * 3 * this.strWei, this.y);
      rotate(PI / 4);
      line(0, noff, 0, this.wy);
      pop();
    }
  }

  display2() {
    strokeWeight(this.strWei);
    //fill(this.col1);
    noFill();
    strokeCap(SQUARE);
    stroke(this.col1);
    var lineNum = int(w / (3 * this.strWei));
    for (let i = 0; i < lineNum + 1; i++) {
      push();
      translate(this.x, this.y + i * 3 * this.strWei);
      rotate(PI / 4);
      line(noff, 0, this.wx, 0);
      pop();
    }
  }
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("BarCODE", "png");
	}
}

